"""Utility functions gathered from various sources or custom.V.1 Oct 2014, BWBV.2 Updated for modern Numpy/Python 3 compatibility (XSimple fix)"""def load_txt_file(path,fil,cols,sep='\t',hdr=True):    """    loads delimited text file of column variables    header, if present, is assumed to be one line of var names only    usage: data, varNames = load_txt_file(path,fil,cols)    inputs: path: string variable for path to file            fil: string variable of file name            cols: number of data columns in file            sep: delimiter character, tab is default            hdr: boolean, True if file has header (default)    output: data: 2-D array of data as column variables            varNames: list of variable names    """    import os    import numpy as np    fpath = os.path.join(path,fil)    fin = open(fpath, 'r') # Added 'r' for clarity    first = True    data = np.zeros((0,cols))    temp = np.zeros((1,cols))    for line in fin:        cleanLine = line.strip()        # Skip empty lines        if not cleanLine:            continue        if first and hdr:            # Handle header            varNames = [x for x in cleanLine.split(sep) if x.strip() != '']            first = False            continue        elif first and not hdr:            varNames = []            for jj in range(cols):  # default var names                varNames.append('var'+str(jj))            first = False        # --- FIX: Split and filter empty strings to prevent ValueError ---        fields = cleanLine.split(sep)        fields = [x for x in fields if x.strip() != '']        # Safety check: if line data is incomplete, skip it        if len(fields) < cols:            continue        for jj in range(cols):            try:                temp[0, jj] = float(fields[jj]) # Python builtin float            except ValueError:                temp[0, jj] = np.nan # Handle non-numeric gracefully        data = np.row_stack((data,temp))    fin.close()    return (data, varNames)def noaa_tcode(ddd, hh, code_str):    """    Converts NOAA serial data acquisition system time code to decimal        julian date.    """    import numpy as np    day = float(ddd)    hr = float(hh)    min = float(code_str[0:2])    sec = float(code_str[2:4])    msec = float(code_str[4:])/1000    jd = day + (hr + (min + (sec + msec)/60)/60)/24;    return jddef find(b):    """    Usage: idx = find(b) - Returns sorted array of indices where boolean    input array b is true.  Similar to MATLAB find function.    """    from numpy import sum, argsort, sort, ndarray    if type(b) != ndarray:        raise ValueError ('find: Input should be ndarray')    if b.dtype != 'bool':        # Try to convert to bool if strictly not bool (optional safety)        pass        # raise ValueError ('find: Input should be boolean array')    if b.ndim > 1:        raise ValueError ('find: Input should be 1-D')    F = b.size - sum(b)    # number of False in b    idx = argsort(b)[F:]   # argsort puts True at the end, so select [F:]    idx = sort(idx)        # be sure values in idx are ordered low to high    return idxdef md2jd(YYYY, MM, DD):    """    Converts Month and Day into day-of-year (julian date)    Returns integer day of year    """    import numpy as np    day_tab = [[31,28,31,30,31,30,31,31,30,31,30,31],               [31,29,31,30,31,30,31,31,30,31,30,31]]    days = np.array(day_tab)    # --- FIX: np.int -> int (for Numpy > 1.20) ---    yr = int(YYYY)    mo = int(MM)    day = int(DD)    leap = np.logical_and((np.remainder(yr,4) == 0),                          (np.remainder(yr,100) != 0))    leap = np.logical_or(leap, (np.remainder(yr,400) == 0))    yday = day    for ii in np.arange(1,mo):        yday += days[leap,ii-1]    return int(yday)def jd2md(YYYY, DOY):    """    Converts day-of-year (julian date) to Month and Day of given Year    Returns tuple of integers, month and day    """    import numpy as np    day_tab = [[31,28,31,30,31,30,31,31,30,31,30,31],               [31,29,31,30,31,30,31,31,30,31,30,31]]    days = np.array(day_tab)    # --- FIX: np.int -> int ---    yr = int(YYYY)    jd = int(DOY)    leap = np.logical_and((np.remainder(yr,4) == 0),                          (np.remainder(yr,100) != 0))    leap = np.logical_or(leap, (np.remainder(yr,400) == 0))    ii = 1    while jd > days[leap,ii-1]:        jd -= days[leap,ii-1]        ii += 1    # --- FIX: np.int -> int ---    mo = int(ii)    day = int(jd)    return (mo, day)def replace_nan(x):    """    Replaces NaNs in 1D array with nearest finite value.    """    import numpy as np    x2 = np.zeros(len(x))    np.copyto(x2,x)    bads = find(np.isnan(x)) # indices of NaNs    if bads.size == 0:        return x2    else:        fins = find(np.isfinite(x))        # indices for all finites        for ii in np.arange(0,bads.size):  # for all NaNs            # locate index of nearest finite            diffs = np.abs(fins-bads[ii])            idx = diffs.argmin()            # replace NaN with nearest finite            x2[bads[ii]] = x[fins[idx]]    return x2def invert_dict(d):    """Inverts a dictionary."""    inverse = {}    # Python 3 compatibility: iteritems -> items    try:        iter_func = d.iteritems()    except AttributeError:        iter_func = d.items()    for key, val in iter_func:        inverse.setdefault(val, []).append(key)    return inversedef find_module(module):    """    Searches the PYTHONPATH for a module    """    import sys    import os    import glob    result = []    for subdir in sys.path:        pth = os.path.join(subdir, module)        res = glob.glob(pth)        if len(res) > 0:            result.append(res)    return resultdef print_attributes(obj):    """    Prints attributes for given object    """    for attr in obj.__dict__:        print(attr), getattr(obj,attr)def walk(dirname):    """    Recursively traverse all files in given directory    """    import os    for name in os.listdir(dirname):        path = os.path.join(dirname,name)        if os.path.isfile(path):            print(path)        else:            walk(path)# Test codeif __name__ == '__main__':    print('test')